"use strict";
function channelButton(kind,label,icon,sub){return `<button class="world-channel channel-${kind}" data-world-channel="${kind}"><span class="channel-icon">${icon}</span><b>${label}</b><small>${sub}</small></button>`;}
function renderTimeHome(){const events=yearEvents[year()]||[],head=events[0];return `<section class="world-home"><div class="world-topline"><span>欢迎回来，${escapeHTML(playState.nickname)}。</span><span>${date.replaceAll('-','.')} · 只读历史世界</span><button data-action="settings">设置</button></div><header class="world-masthead"><div><small>INTERNET TIME MACHINE</small><h1>考古浏览器<span>OLD DAYS</span></h1></div><p>把那个年代，<br>再过一遍。</p><div class="world-year-stamp"><b>${year()}</b><span>TIME IS HERE</span></div></header><nav class="world-main-nav">${[['home','时光首页'],['news','新闻'],['music','音乐'],['videos','视频'],['books','小说'],['games','游戏']].map(([k,t])=>`<button class="${k==='home'?'selected':''}" data-world-channel="${k}">${t}</button>`).join('')}<button data-memory-gallery>图文</button><button data-community="tianya">社区</button><button data-anime-club>动漫</button><button data-kiosk-open>报刊亭</button><button data-phone-lab>旧手机</button><button data-gadget-open>MP3 / 设备馆</button><button data-poster-room>年代画报</button><button data-open-skins>换肤</button></nav><div class="world-subnav"><span>你的年代 →</span>${[1999,2001,2004,2005,2008,2010,2018].map(y=>`<button data-year="${y}" class="${year()===String(y)?'selected':''}">${y}</button>`).join('')}<button id="world-more-date" data-open-date>更多年份</button><button data-capture-view>▧ 截图</button></div><div class="world-marquee"><span>✉ 来自过去的消息</span><p>网速很慢，期待很长。欢迎回到 ${year()} 年的互联网。</p><button data-phone-lab>拆开一部旧手机 &gt;&gt;</button></div><div class="world-lead-ad">${eraAdvertMarkup('banner')}</div><div class="world-channel-row">${channelButton('news','新闻中心','报','读一读那年的世界')}${channelButton('music','音乐随身听','♪','把旋律装进口袋')}${channelButton('videos','掌上放映室','▶','回看留存的影像')}${channelButton('books','掌上书房','书','被窝里的阅读时光')}${channelButton('games','像素游戏厅','▦','再玩一局就睡')}</div><section class="home-midnight"><button class="home-midnight-picture" data-picture-story="one-seventeen"><img src="images/memories/night.jpg" alt="被窝里看旧手机的怀旧创作配图"><span><small>01:17 / 深夜图文馆</small><b>凌晨一点十七分，<br>你怎么还没睡。</b><em>点开图片，读一个故事 →</em></span></button><div class="home-community-door"><small>OLD FRIENDS / 社区客厅</small><h2>还有人没下线。</h2><p>翻长帖、踩空间、留一句晚安。<br>回到那个一层一层等回复的晚上。</p><button data-community="tianya">去社区坐坐 →</button><button data-memory-gallery>搜图片 / 找故事</button></div></section><div class="world-main-columns"><div class="world-news-column"><section class="world-panel panel-news"><header><h2>${year()} 年大新闻</h2><button data-news-center>更多新闻 &gt;&gt;</button></header><div class="world-feature-news"><small>${year()} 年度焦点</small><button data-news-year="${year()}" data-news-index="0">${escapeHTML(head?.[1]||'翻开那一年的记忆')}</button><p>每年十篇精选长文，另有 ${yearbookCounts[year()]||0} 条年表记录。按月份找一找那时的大事。</p></div><div class="world-news-list">${events.slice(1,8).map((n,i)=>`<a href="archaeo://news/${year()}/${i+1}" data-news-year="${year()}" data-news-index="${i+1}"><time>${n[0]}</time><span>${escapeHTML(n[1])}</span><b>›</b></a>`).join('')}</div><footer><button data-news-center>进入 ${year()} 年新闻中心 →</button><small>历史资料整理，非当年即时报道</small></footer></section><section class="world-panel panel-listening"><header><h2>听见 · 旧时光</h2><button data-world-channel="music">音乐频道 &gt;&gt;</button></header><div class="home-music-deck"><div class="home-cd-art"><i>♪</i></div><div><small>OLD DAYS PERSONAL STEREO</small><h3>口袋里的那首歌</h3><p>手动播放 · 原创合成旋律</p><button data-music-toggle>${$('#retro-audio').paused?'▶ 播放配乐':'Ⅱ 暂停配乐'}</button><button data-world-channel="music">打开播放列表</button></div></div></section></div><aside class="world-pocket-column"><section class="world-pocket-card"><small>口袋时光机 / POCKET LAB</small><h2>你的第一部手机，<br>还记得怎么用吗？</h2><div class="pocket-card-art">${advertArt({art:'phone'})}<span>短信 / 贪吃蛇 / 壁纸<br>新闻 / 音乐 / 小说</span></div><button data-phone-lab>进入那部旧手机 →</button><div class="pocket-models"><button data-phone-preset="nokia3310">黑白屏</button><button data-phone-preset="symbian">彩色屏</button><button data-phone-preset="razr">翻盖机</button><button data-phone-preset="iphone">初代触屏</button></div><p>按键能点，页面能翻，<br>还可以保存带手机外壳的截图。</p></section><div class="world-side-ad">${eraAdvertMarkup('small',2)}</div></aside></div>${posterStrip("home")}<div class="world-middle-ad">${eraAdvertMarkup('strip',3)}</div><div class="world-play-columns"><section class="world-panel"><header><h2>看见 · 宽频年代</h2><button data-world-channel="videos">视频 &gt;&gt;</button></header><button class="world-cinema-card" data-world-channel="videos"><div class="cinema-curtain"><i>▶</i><span>OLD DAYS PICTURE HOUSE</span></div><h3>小小窗口里，放映大世界。</h3><p>${Number(year())>=2001?'年代影像 · 老视频站 · 手机内播放':'视频旧址 · 闪客文化 · 当年的宽频页面'}</p></button></section><section class="world-panel"><header><h2>读到 · 深夜两点</h2><button data-bookshelf>书房 &gt;&gt;</button></header><div class="home-books-row">${readingShelf().slice(0,3).map((b,i)=>`<button class="home-tiny-book tiny-book-${i}" data-open-book="${b.id}"><span>${b.title}</span><small>${b.author}</small></button>`).join('')}</div><p class="world-panel-note">原创短篇 / 公版经典 / 本机续读<br>也能去旧手机里读，再存一张截图。</p></section><section class="world-panel"><header><h2>再来 · 最后一局</h2><button data-world-channel="games">游戏 &gt;&gt;</button></header><div class="home-game-links"><button data-start-snake><span class="pixel-snake-art">■■■<br>　　■<br>　■■　▪</span><b>贪吃蛇</b><small>在旧手机里挑战</small></button><button data-arcade="mines"><span class="pixel-mine-art">1 ▧ ▧<br>2 ✹ ▧<br>1 2 1</span><b>像素扫雷</b><small>第一下总是安全的</small></button></div><div class="world-small-links"><button data-scene="garden">开心菜园</button><button data-scene="wutang">精武堂</button><button data-arcade="blocks">方块堆叠</button></div></section></div><section class="world-ad-strip"><div><small>MEMORY MAGAZINE / 最后一页</small><h2>“编辑短信，发送到……”</h2><p>彩铃、壁纸、游戏点卡，那些翻到书后面才看见的小广告。</p><button data-ad-magazine>翻开年代杂志封底 →</button></div><div class="classified-mini"><b>个性手机 DIY</b><strong>铃声 / 壁纸 / 心情短信</strong><span>发送「铃声01」到 <em>106XXXX</em></span><small>本机演示 · 非真实付费服务</small></div></section><details class="world-directory"><summary>旧站大全 · 240 个候选历史入口 <span>展开寻找旧网址</span></summary><div class="world-directory-desktop">${catalogMarkup('desktop-catalog')}</div><div class="world-directory-mobile">${catalogMarkup('mobile-catalog')}</div></details><footer class="world-footer"><span>考古浏览器 / OLD DAYS</span><p>不是所有过去都能找回，但每一段留下的记录，都值得再看一次。</p><div><button data-action="sources">资料来源</button><button data-open-skins>年代换肤</button><button data-phone-lab>口袋时光机</button><button data-capture-view>保存截图</button></div><small>本站为原创怀旧体验。新闻为后期历史资料整理；广告、手机外壳和小游戏均有重制标注。</small></footer></section>`;}
function renderGamesHall(){return `<section class="games-hall"><header><small>ONE MORE GAME / 最后一局</small><h1>那时的快乐，几个按键就够了。</h1><p>不用安装，点开就玩。经典玩法为本站原创重制，Java ME 区会单独标明真实运行环境。</p><button data-action="home">返回首页</button><button data-phone-lab>在旧手机里玩</button></header><div class="games-hall-grid"><button data-start-snake><span class="game-poster poster-snake"><i>■■■■<br>　　　■<br>　■■■　▪</i></span><b>贪吃蛇</b><small>方向键 / 数字键 / 手机实体按键</small><em>开始游戏 →</em></button><button data-arcade="mines"><span class="game-poster poster-mines"><i>1 2 ▧ ▧<br>2 ✹ 3 ▧<br>1 2 2 1</i></span><b>像素扫雷</b><small>8×8 棋盘 / 第一格安全</small><em>开始游戏 →</em></button><button data-arcade="blocks"><span class="game-poster poster-blocks"><i>▟<br>▦ ▙<br>▦▦▦▟</i></span><b>方块堆叠</b><small>移动 / 旋转 / 满行消除</small><em>开始游戏 →</em></button><button data-scene="garden"><span class="game-poster poster-garden"><i>田 田 田<br>田 田 田</i></span><b>开心菜园</b><small>六块小田 / 本机保存进度</small><em>去种菜 →</em></button><button data-scene="wutang"><span class="game-poster poster-wutang"><i>武<br>一招一式</i></span><b>精武堂</b><small>练功 / 闯关 / 打坐恢复</small><em>进入江湖 →</em></button><button data-javame-room><span class="game-poster poster-java"><i>JAVA<br>ME</i></span><b>Java ME 实验室</b><small>原创 Java 游戏与工具 / 导入本机 JAR</small><em>查看 Java 程序 →</em></button></div>${posterStrip("games")}</section>`;}
function openWorldChannel(kind){if(kind==='home')return navigate({type:'home'});if(kind==='news')return openNewsCenter();if(kind==='books')return openBookshelf();if(kind==='games')return navigate({type:'games',name:'像素游戏厅',url:'archaeo://games'});if(kind==='music'||kind==='videos')return navigate({type:kind,name:kind==='music'?'音乐随身听':'掌上放映室',url:'archaeo://'+kind});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-world-channel],[data-phone-preset],[data-start-snake],[data-open-date]');if(!b)return;e.preventDefault();if(b.dataset.worldChannel)openWorldChannel(b.dataset.worldChannel);if(b.dataset.phonePreset&&Object.hasOwn(phoneModels,b.dataset.phonePreset)){phoneState.model=b.dataset.phonePreset;openPhoneLab('home');}if(b.hasAttribute('data-start-snake')){openPhoneLab('snake');startPhoneSnake();}if(b.hasAttribute('data-open-date'))dateDialog();});
